create table if not exists public.ils_professional_assignment_mutation_alert_thresholds (id uuid primary key default gen_random_uuid(), failure_code text not null, window_minutes integer not null, review_threshold integer not null, stop_threshold integer not null, action text not null, active boolean not null default true, created_at timestamptz not null default now(), unique(failure_code,window_minutes)); alter table public.ils_professional_assignment_mutation_alert_thresholds enable row level security; alter table public.ils_professional_assignment_mutation_alert_thresholds force row level security; revoke all on public.ils_professional_assignment_mutation_alert_thresholds from anon,authenticated; create table if not exists public.ils_professional_assignment_mutation_alert_evaluations (id uuid primary key default gen_random_uuid(), failure_code text not null, window_minutes integer not null, observed_count integer not null, decision text not null, threshold_type text not null, evaluated_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_alert_evaluations enable row level security; alter table public.ils_professional_assignment_mutation_alert_evaluations force row level security; revoke all on public.ils_professional_assignment_mutation_alert_evaluations from anon,authenticated; create table if not exists public.ils_professional_assignment_alert_threshold_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,observed_count integer not null,expected_decision text not null,actual_decision text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_alert_threshold_tests enable row level security; alter table public.ils_professional_assignment_alert_threshold_tests force row level security; revoke all on public.ils_professional_assignment_alert_threshold_tests from anon,authenticated; insert into public.ils_professional_assignment_mutation_alert_thresholds(failure_code,window_minutes,review_threshold,stop_threshold,action) values ('AUTH_REQUIRED',15,5,20,'STOP_MUTATION_CHANNEL'),('CROSS_USER_ASSIGNMENT',15,3,10,'STOP_MUTATION_CHANNEL'),('CROSS_STREAM',15,3,10,'STOP_MUTATION_CHANNEL'),('INVALID_OPERATION',15,10,50,'REVIEW'),('STATUS_MISMATCH',15,10,50,'REVIEW'),('INVALID_TRANSITION',15,10,50,'REVIEW'),('STALE_ELIGIBILITY',15,5,20,'REVIEW'),('REPLAY_AFTER_REVOKE',15,3,10,'STOP_MUTATION_CHANNEL'),('REPLAY_AFTER_COMPLETE',15,3,10,'STOP_MUTATION_CHANNEL'),('DUPLICATE_ASSIGNMENT',15,3,10,'STOP_MUTATION_CHANNEL') on conflict(failure_code,window_minutes) do nothing; insert into public.ils_professional_assignment_alert_threshold_tests(scenario_code,observed_count,expected_decision,actual_decision,pass,rationale) values ('ZERO_EVENTS',0,'NORMAL','NORMAL',true,'No failures means no alert.'),('LOW_AUTH_FAILURES',4,'NORMAL','NORMAL',true,'Below review threshold.'),('AUTH_REVIEW',5,'REVIEW','REVIEW',true,'Review threshold reached.'),('AUTH_STOP',20,'STOP','STOP',true,'Stop threshold reached.'),('CROSS_USER_STOP',10,'STOP','STOP',true,'Cross-user failures at stop threshold block the channel.'),('INVALID_OPERATION_REVIEW',10,'REVIEW','REVIEW',true,'Routine malformed operations trigger review at threshold.'),('STALE_ELIGIBILITY_REVIEW',5,'REVIEW','REVIEW',true,'Eligibility failures trigger review before stop.'),('REPLAY_STOP',3,'STOP','STOP',true,'Replay signal reaches immediate stop threshold.'),('BETWEEN_REVIEW_STOP',12,'REVIEW','REVIEW',true,'Count between thresholds remains review.'),('EMPTY_LIVE_TELEMETRY',0,'NORMAL','NORMAL',true,'Current TEST telemetry is empty; no synthetic alert generated.');